"""User-account service: registration, login, and password reset via one-time tokens."""


class AccountService:
    def __init__(self) -> None:
        # email (lowercased) -> {"password": str, "is_admin": bool}
        self._accounts: dict[str, dict] = {}
        # token -> target email (lowercased); presence means "unused"
        self._reset_tokens: dict[str, str] = {}
        self._token_counter = 0

    @staticmethod
    def _normalize(email: str) -> str:
        return email.strip().lower()

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        key = self._normalize(email)
        if key in self._accounts:
            raise ValueError(f"Account already exists for {email!r}")
        self._accounts[key] = {"password": password, "is_admin": bool(is_admin)}

    def login(self, email: str, password: str) -> bool:
        account = self._accounts.get(self._normalize(email))
        if account is None:
            return False
        return account["password"].lower() == password.lower()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester = self._accounts.get(self._normalize(requester_email))
        if requester is None or not requester["is_admin"]:
            raise PermissionError("Only administrators can request password resets.")
        target_key = self._normalize(target_email)
        if target_key not in self._accounts:
            raise ValueError(f"No account found for {target_email!r}")
        self._token_counter += 1
        token = f"reset-token-{self._token_counter}"
        self._reset_tokens[token] = target_key
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if token not in self._reset_tokens:
            raise ValueError("Invalid or already-used reset token.")
        target_key = self._reset_tokens.pop(token)
        self._accounts[target_key]["password"] = new_password
